<script setup lang="ts">
/**
 * A scatter chart for correlation between two measures (`design/components/scatter-chart.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/scatter-chart.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useTemplateRef, watch } from 'vue'

import {
  DEFAULT_CHART_MESSAGES,
  Icon,
  UNMEASURED,
  agentMember,
  chartHiddenSeries,
  chartMarks,
  chartPosition,
  chartSeries,
  chooseChartMark,
  createReading,
  createWarningLog,
  devWarning,
  measureBox,
  nearest2D,
  readChartCap,
  readChartPosition,
  readingRest,
  readingView,
  scatterChartModel,
  scatterChartReadout,
  scatterChartSelection,
  toggleChartSeries,
  toggleSeries,
  useListening,
  type ChartAnnotation,
  type ChartMessages,
  type ChartSeries,
  type ChartTooltipConfig,
  type ChartXAxis,
  type ChartYAxis,
  type ScatterBubble,
} from '@polymorph/vue'
import styles from '@polymorph/recipes/charts/scatter-chart.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import chartAxis from '@polymorph/recipes/charts/frame/chart-axis.module.css'
import chartFrame from '@polymorph/recipes/charts/frame/chart-frame.module.css'
import chartLegend from '@polymorph/recipes/charts/frame/chart-legend.module.css'
import chartNotes from '@polymorph/recipes/charts/frame/chart-annotations.module.css'
import chartTooltip from '@polymorph/recipes/charts/frame/chart-tooltip.module.css'
import chartTwin from '@polymorph/recipes/charts/frame/chart-twin.module.css'
import Button from '../controls/Button.vue'
import Table from '../structure/Table.vue'
import TableBody from '../structure/TableBody.vue'
import TableCell from '../structure/TableCell.vue'
import TableHead from '../structure/TableHead.vue'
import TableHeader from '../structure/TableHeader.vue'
import TableRow from '../structure/TableRow.vue'

export interface ScatterChartProps {
  /**
   * Annotations from the tier's closed union (line, band and point), all allowed on this member.
   */
  annotations?: readonly ChartAnnotation[]
  bubble?: ScatterBubble
  /**
   * One row per observation. A `null` x, y or bubble value renders **no mark** for that row and
   * series (shown as — in the twin), never a zero.
   */
  data: readonly Readonly<Record<string, string | number | null>>[]
  /**
   * The accessible name.
   */
  label: string
  /**
   * Shows the previous frame at reduced opacity during a refetch.
   */
  loading?: boolean
  /**
   * The locale for `Intl` formatting.
   */
  locale?: string
  /**
   * The chart tier's string catalog (`ChartMessages`). Defaults to generic English; a localized
   * host passes the same object to every chart.
   */
  messages?: ChartMessages
  /**
   * The series, **at most the palette's cap**. The member reads `--pm-chart-cap` (emitted by the
   * theme at the minimum across modes) and dev-warns above it.
   */
  series: readonly ChartSeries[]
  size?: 'sm' | 'md' | 'lg'
  /**
   * The per-mark readout (no crosshair): the x, y and bubble values, each in its own format.
   */
  tooltip?: false | ChartTooltipConfig
  /**
   * The x axis, `linear` or `time`. An omitted `scale` defaults to `'linear'` here, not
   * `'band'`, because a scatter's x is a measure. `band` raises a dev warning naming BarChart,
   * and the axis renders linear.
   */
  x: ChartXAxis
  /**
   * The y axis. `domain` defaults to `'auto'` to fit the data; `'zero'` anchors at zero.
   */
  y?: ChartYAxis
}

defineOptions({ name: 'ScatterChart', inheritAttrs: false })

const props = withDefaults(defineProps<ScatterChartProps>(), {
  loading: false,
  messages: () => DEFAULT_CHART_MESSAGES,
  size: 'md',
  tooltip: () => ({}),
})
const emit = defineEmits<{
  select: [
    selection: {
      index: number
      key: string
      datum: Readonly<Record<string, string | number | null>>
    },
  ]
}>()
const listening = useListening()
const box = ref(UNMEASURED)
const reading = ref(createReading({ count: 0, seriesStart: 0 }))
const position = ref(readingRest(0))
const hidden = ref(new Set<string>())
const twinOpen = ref(false)
const warningLog = ref(createWarningLog())
const cap = ref(readChartCap(null))
const frame = useTemplateRef<HTMLElement>('frame')
const plot = useTemplateRef<HTMLElement>('plot')
const input = computed(() => ({
  data: props.data,
  series: props.series,
  x: props.x,
  y: props.y,
  bubble: props.bubble,
  annotations: props.annotations,
  label: props.label,
  locale: props.locale,
  messages: props.messages,
  tooltip: props.tooltip,
  loading: props.loading,
  selectable: listening.select,
  hidden: hidden.value,
  cap: cap.value,
  box: box.value,
}))
const model = computed(() => scatterChartModel(input.value))
const view = computed(() =>
  readingView(position.value, props.data.length, model.value.visible.length),
)
const readout = computed(() => scatterChartReadout(input.value, model.value, view.value))
const walked = computed(() => view.value.series ?? 0)
const activate = computed(() => () => {
  const selection = scatterChartSelection(input.value, model.value, reading.value.now())
  if (selection !== null) emit('select', selection)
})
const walk = computed(() => ({
  count: props.data.length,
  seriesCount: model.value.visible.length,
  walkSeries: true,
  seriesStart: 0,
}))
const marks = computed(() => ({
  walk: walk.value,
  input: input.value,
  model: model.value,
  readout: scatterChartReadout,
  selection: scatterChartSelection,
}))
const onKey = computed(() => (event: KeyboardEvent) => {
  if (listening.select && (event.key === 'Enter' || event.key === ' ')) {
    event.preventDefault()
    activate.value()
    return
  }
  reading.value.update(walk.value)
  if (reading.value.key(event.key)) event.preventDefault()
})
const onPointer = computed(() => (event: PointerEvent) => {
  if (model.value.plot === null) return
  const rect = (event.currentTarget as Element).getBoundingClientRect()
  const hit = nearest2D(model.value.points, event.clientX - rect.left, event.clientY - rect.top)
  if (hit === -1) {
    reading.value.clear()
    return
  }
  reading.value.moveTo(hit % props.data.length, Math.floor(hit / props.data.length))
})
const effect1 = () => {
  cap.value = model.value.state === 'empty' ? cap.value : readChartCap(plot.value)
}
onMounted(effect1)
watch(() => model.value.state === 'empty', effect1, { flush: 'post' })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const run = () => {
    box.value = plot.value === null ? box.value : measureBox(plot.value, box.value)
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [plot.value]) if (element) resize?.observe(element)
  release2 = () => {
    resize?.disconnect()
  }
  run()
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
const effect3 = () => {
  reading.value.subscribe((now) => {
    position.value = now
  })
}
onMounted(effect3)
const effect4 = () => {
  warningLog.value.log(model.value.warnings, (message) => devWarning(true, message))
}
onMounted(effect4)
watch(() => model.value.warnings.join('\n'), effect4, { flush: 'post' })
let release5: (() => void) | undefined
const effect5 = () => {
  release5?.()
  const ran =
    !listening.select && !model.value.legend
      ? () => {}
      : agentMember({
          member: 'ScatterChart',
          element: () => frame.value,
          state: () => ({
            items: listening.select ? chartMarks(marks.value, reading.value) : [],
            position: chartPosition(marks.value, reading.value),
            count: walk.value.count,
            series: chartSeries(frame.value, chartLegend.key, model.value.painted),
            hidden: chartHiddenSeries(frame.value, chartLegend.key, model.value.painted),
          }),
          actions: {
            read: {
              argument: 'number',
              run: (value) => readChartPosition(marks.value, value, reading.value),
            },
            choose: {
              argument: 'id',
              among: 'items',
              run: (value) => chooseChartMark(marks.value, value, reading.value, activate.value),
            },
            toggle: {
              argument: 'id',
              among: 'series',
              run: (value) =>
                toggleChartSeries(frame.value, chartLegend.key, model.value.painted, value),
            },
          },
        })
  release5 = () => {
    ran()
  }
}
onMounted(effect5)
onBeforeUnmount(() => release5?.())
</script>

<template>
  <figure
    ref="frame"
    :class="chartFrame.frame"
    :data-size="size"
    :data-state="model.state"
    :data-position="view.active ? view.index : undefined"
    :aria-label="label"
    data-member="scatter-chart"
  >
    <!-- region -->
    <div :class="chartFrame.region">
      <!-- y axis -->
      <div :class="chartFrame.yAxis">
        <!-- y axis ticks -->
        <div
          v-if="model.axes?.y !== undefined"
          :class="chartAxis.axis"
          data-orientation="y"
          aria-hidden="true"
        >
          <template v-for="tick in model.axes?.y ?? []" :key="tick.key">
            <span :class="chartAxis.tick" :style="{ top: `${tick.at}px` }" :data-align="tick.align">
              {{ tick.label }}
            </span>
          </template>
        </div>
      </div>
      <!-- plot -->
      <div ref="plot" :class="chartFrame.plot">
        <div v-if="model.state === 'empty'" :class="chartFrame.empty">
          <span>
            {{ messages.empty }}
          </span>
        </div>
        <!-- surface -->
        <div
          v-else
          :class="styles.surface"
          tabindex="0"
          role="img"
          :aria-label="label"
          @keydown="onKey($event)"
          @click="activate()"
          @pointermove="onPointer($event)"
          @pointerleave="reading.clear()"
          @blur="reading.clear()"
        >
          <!-- marks -->
          <svg
            v-if="model.plot !== null"
            :class="styles.marks"
            :data-reading="view.active ? '' : undefined"
            :width="model.plot?.width"
            :height="model.plot?.height"
            aria-hidden="true"
            focusable="false"
          >
            <!-- grid -->
            <g :class="styles.grid">
              <template v-for="line in model.plot?.grid ?? []" :key="line.key">
                <path :d="line.d" />
              </template>
            </g>
            <template v-for="rule in model.plot?.zero ?? []" :key="rule.key">
              <!-- zero -->
              <path :class="styles.zero" :d="rule.d" />
            </template>
            <!-- annotation wash -->
            <g v-if="(model.plot?.wash ?? []).length > 0" :class="chartNotes.washes">
              <template v-for="span in model.plot?.wash ?? []" :key="span.key">
                <rect
                  :class="chartNotes.span"
                  :x="span.x"
                  :y="span.y"
                  :width="span.width"
                  :height="span.height"
                />
              </template>
            </g>
            <!-- points -->
            <g :class="styles.points">
              <template v-for="group in model.plot?.groups ?? []" :key="group.key">
                <g
                  :style="{ '--pm-chart-mark': group.paint }"
                  :data-active="view.active && walked === group.series ? '' : undefined"
                >
                  <template v-for="dot in group.dots" :key="dot.index">
                    <circle
                      :class="styles.dot"
                      :style="{ '--pm-chart-dot': dot.index }"
                      :cx="dot.cx"
                      :cy="dot.cy"
                      :r="dot.r"
                      :data-active="
                        view.index === dot.index && walked === group.series ? '' : undefined
                      "
                    />
                  </template>
                </g>
              </template>
            </g>
            <!-- annotation ink -->
            <g v-if="(model.plot?.ink ?? null) !== null" :class="chartNotes.ink">
              <template v-for="span in (model.plot?.ink ?? null)?.spans ?? []" :key="span.key">
                <g>
                  <path :class="chartNotes.edge" :d="span.from" />
                  <path :class="chartNotes.edge" :d="span.to" />
                </g>
              </template>
              <template v-for="rule in (model.plot?.ink ?? null)?.rules ?? []" :key="rule.key">
                <path :class="chartNotes.rule" :d="rule.d" />
              </template>
              <template v-for="mark in (model.plot?.ink ?? null)?.marks ?? []" :key="mark.key">
                <circle :class="chartNotes.mark" :cx="mark.cx" :cy="mark.cy" :r="mark.r" />
              </template>
              <template v-for="note in (model.plot?.ink ?? null)?.labels ?? []" :key="note.key">
                <text :class="chartNotes.label" :x="note.x" :y="note.y" :text-anchor="note.anchor">
                  {{ note.text }}
                </text>
              </template>
            </g>
          </svg>
        </div>
        <!-- tooltip -->
        <div
          v-if="readout.tooltip !== null"
          :class="chartTooltip.tooltip"
          :style="{
            '--pm-chart-tip-x': `${readout.tooltip?.x}px`,
            '--pm-chart-tip-y': `${readout.tooltip?.y}px`,
          }"
          :data-indicator="readout.tooltip?.indicator"
          :data-side="readout.tooltip?.side"
          aria-hidden="true"
        >
          <p v-if="readout.tooltip?.header !== undefined" :class="chartTooltip.header">
            {{ readout.tooltip?.header }}
          </p>
          <ul :class="chartTooltip.rows">
            <template v-for="row in readout.tooltip?.rows ?? []" :key="row.key">
              <li :class="chartTooltip.row">
                <span :class="chartTooltip.key" :style="{ '--pm-chart-key': row.paint }" />
                <span :class="chartTooltip.value">
                  {{ row.value }}
                </span>
                <span :class="chartTooltip.label">
                  {{ row.label }}
                </span>
              </li>
            </template>
          </ul>
        </div>
      </div>
      <!-- x axis -->
      <div :class="chartFrame.xAxis">
        <!-- x axis ticks -->
        <div
          v-if="model.axes?.x !== undefined"
          :class="chartAxis.axis"
          data-orientation="x"
          aria-hidden="true"
        >
          <template v-for="tick in model.axes?.x ?? []" :key="tick.key">
            <span
              :class="chartAxis.tick"
              :style="{ left: `${tick.at}px` }"
              :data-align="tick.align"
            >
              {{ tick.label }}
            </span>
          </template>
        </div>
      </div>
    </div>
    <template v-if="model.legend">
      <!-- legend -->
      <ul v-if="model.painted.length > 0" :class="styles.legend" data-key-shape="rect">
        <template v-for="entry in model.painted" :key="entry.key">
          <li :class="chartLegend.item">
            <button
              :class="chartLegend.key"
              type="button"
              :aria-pressed="hidden.has(entry.key) ? 'false' : 'true'"
              @click="hidden = toggleSeries(hidden, entry.key)"
            >
              <span
                :class="chartLegend.swatch"
                :style="{ '--pm-chart-key': entry.paint }"
                aria-hidden="true"
              />
              <span v-if="entry.icon !== undefined" :class="chartLegend.glyph">
                <Icon :name="entry.icon" size="sm" />
              </span>
              <span :class="chartLegend.label">
                {{ entry.label }}
              </span>
            </button>
          </li>
        </template>
      </ul>
    </template>
    <!-- summary -->
    <span :class="a11y.visuallyHidden">
      {{ model.summary }}
    </span>
    <!-- twin -->
    <div :class="chartTwin.twin" :data-state="twinOpen ? 'open' : 'closed'">
      <div :class="chartTwin.toggle">
        <Button
          variant="ghost"
          tone="neutral"
          size="sm"
          icon="table"
          :iconOnly="true"
          :label="twinOpen ? messages.hideTable(label) : messages.showTable(label)"
          @click="twinOpen = !twinOpen"
        />
      </div>
      <div v-if="twinOpen" :class="chartTwin.table">
        <Table :label="messages.tableLabel(label)" :caption="messages.tableLabel(label)">
          <TableHead>
            <TableRow>
              <template v-for="column in model.twin.columns" :key="column.key">
                <TableHeader :numeric="column.numeric">
                  {{ column.label }}
                </TableHeader>
              </template>
            </TableRow>
          </TableHead>
          <TableBody>
            <template v-for="(row, line) in model.twin.rows" :key="line">
              <TableRow>
                <template
                  v-for="(cell, cellIndex) in row"
                  :key="model.twin.columns[cellIndex]?.key ?? cellIndex"
                >
                  <TableCell :numeric="model.twin.columns[cellIndex]?.numeric">
                    {{ cell === '' ? '—' : cell }}
                  </TableCell>
                </template>
              </TableRow>
            </template>
          </TableBody>
        </Table>
      </div>
    </div>
    <!-- live region -->
    <span :class="a11y.visuallyHidden">
      <div aria-live="polite" aria-atomic="true">
        {{ readout.announcement }}
      </div>
    </span>
  </figure>
</template>
